 }
 if($api==='login'){$un=T($_POST['username']??'',80);$pw=(string)($_POST['password']??'');foreach(R('users.json') as $x){if(($x['username']??'')===$un){$s=(string)$x['password'];$ok=password_verify($pw,$s)||(strlen($s)<100&&hash_equals($s,$pw));if($ok){session_regenerate_id(true);$_SESSION['user']=['id'=>$x['id'],'username'=>$x['username'],'role'=>$x['role']];J(true,'Login berhasil.',$_SESSION['user']);}}}J(false,'Username atau password salah.',null,401);}
 if($api==='logout'){$_SESSION=[];session_destroy();J(true,'Logout berhasil.');}
 if($api==='upload'){U();if(empty($_FILES['file'])||$_FILES['file']['error']!==0)J(false,'Upload gagal.',null,422);$f=$_FILES['file'];if($f['size']>5242880)J(false,'Maksimal 5 MB.',null,422);$m=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ok=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($ok[$m]))J(false,'Format gambar tidak didukung.',null,422);$name=bin2hex(random_bytes(12)).'.'.$ok[$m];move_uploaded_file($f['tmp_name'],UP.$name);chmod(UP.$name,0644);J(true,'Upload berhasil.','uploads/'.$name);}
 if($api==='save-news'){$u=U();$a=R('berita.json');$id=T($_POST['id']??'',80);$old=null;foreach($a as $x)if(($x['id']??'')===$id)$old=$x;if($old&&$u['role']!=='admin'&&($old['nama_penulis']??'')!==$u['username'])J(false,'Anda hanya dapat mengedit berita sendiri.',null,403);if(!$old)$id=bin2hex(random_bytes(8));$cat=T($_POST['kategori']??'',30);$cats=['Nasional','Ekonomi','Olahraga','Hiburan','Kuliner'];$desc=T($_POST['meta_desc']??'',140);$tags=array_slice(array_values(array_filter(array_map(fn($v)=>T($v,50),explode(',',(string)($_POST['meta_tags']??''))))),0,4);$item=['id'=>$id,'tanggal'=>$old['tanggal']??date('c'),'judul'=>T($_POST['judul']??'',220),'meta_desc'=>$desc,'meta_tags'=>implode(', ',$tags),'gambar'=>T($_POST['gambar']??'',1000),'konten'=>(string)($_POST['konten']??''),'kategori'=>$cat,'nama_penulis'=>$old['nama_penulis']??$u['username']];if($item['judul']===''||$desc===''||trim(strip_tags($item['konten']))===''||!in_array($cat,$cats,true))J(false,'Lengkapi judul, meta description, kategori dan konten.',null,422);$found=false;foreach($a as $i=>$x)if(($x['id']??'')===$id){$a[$i]=$item;$found=true;}if(!$found)$a[]=$item;W('berita.json',$a);J(true,'Berita tersimpan.',$item);}
 if($api==='delete-news'){$u=U();$id=T($_POST['id']??'',80);$a=R('berita.json');foreach($a as $x)if(($x['id']??'')===$id&&$u['role']!=='admin'&&($x['nama_penulis']??'')!==$u['username'])J(false,'Anda hanya dapat menghapus berita sendiri.',null,403);$a=array_values(array_filter($a,fn($x)=>($x['id']??'')!==$id));W('berita.json',$a);J(true,'Berita dihapus.');}
 if($api==='save-menu'){A();$a=R('menu.json');$id=T($_POST['id']??'',50)?:bin2hex(random_bytes(4));$it=['id'=>$id,'nama'=>T($_POST['nama']??'',80),'link'=>T($_POST['link']??'',300)];foreach($a as $i=>$x)if(($x['id']??'')===$id)$a[$i]=$it;if(!in_array($it['id'],array_column($a,'id'),true))$a[]=$it;W('menu.json',$a);J(true,'Menu tersimpan.');}
 if($api==='delete-menu'){A();$id=T($_POST['id']??'',50);W('menu.json',array_values(array_filter(R('menu.json'),fn($x)=>($x['id']??'')!==$id)));J(true,'Menu dihapus.');}
 if($api==='save-user'){A();$a=R('users.json');$id=T($_POST['id']??'',50);$un=T($_POST['username']??'',80);$role=$_POST['role']??'penulis';$pw=(string)($_POST['password']??'');if(!$un||!in_array($role,['admin','penulis'],true))J(false,'Data user tidak valid.',null,422);foreach($a as $i=>$x){if(strtolower($x['username']??'')===strtolower($un)&&($x['id']??'')!==$id)J(false,'Username sudah digunakan.',null,409);if(($x['id']??'')===$id){$a[$i]['username']=$un;$a[$i]['role']=$role;if($pw!=='')$a[$i]['password']=password_hash($pw,PASSWORD_DEFAULT);}}if(!$id){if($pw==='')J(false,'Password wajib.',null,422);$a[]=['id'=>bin2hex(random_bytes(8)),'username'=>$un,'password'=>password_hash($pw,PASSWORD_DEFAULT),'role'=>$role];}W('users.json',$a);J(true,'User tersimpan.');}
 if($api==='delete-user'){ $me=A();$id=T($_POST['id']??'',50);if($id===$me['id'])J(false,'Tidak dapat menghapus akun sendiri.',null,422);W('users.json',array_values(array_filter(R('users.json'),fn($x)=>($x['id']??'')!==$id)));J(true,'User dihapus.');}
 J(false,'API tidak dikenal.',null,400);
}
$news=R('berita.json');usort($news,fn($a,$b)=>strtotime($b['tanggal']??'')<=>strtotime($a['tanggal']??''));$id=$_GET['id']??null;$cat=$_GET['kategori']??null;
function h($s):string{return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
