</style></head><body><?php if(!$user): ?><div class="login"><form class="box" id="login"><img src="uploads/logo_KSA.jpg" style="max-width:220px;display:block;margin:auto"><h2>CMS INT Media Network</h2><input name="username" placeholder="Username" required><input name="password" type="password" placeholder="Password" required><button class="red" style="width:100%">Login</button><p id="err"></p></form></div><script>login.onsubmit=async e=>{e.preventDefault();let f=new FormData(login);let r=await fetch('?api=login',{method:'POST',body:f}),j=await r.json();j.success?location.reload():err.textContent=j.message}</script><?php else: ?><div class="layout"><aside class="side"><img src="uploads/logo_KSA.jpg"><button onclick="show('dash')">Dasbor</button><button onclick="show('news')">Kelola Berita</button><?php if($user['role']==='admin'): ?><button onclick="show('menu')">Kelola Menu</button><button onclick="show('users')">Manajemen User</button><?php endif; ?><button onclick="logout()">Keluar</button></aside><main><h1>CMS Redaksi</h1><small><?=h($user['username'])?> · <?=h($user['role'])?></small><section id="dash" class="panel on box"><h2>Dasbor</h2><p>Total berita: <b id="total">0</b></p></section><section id="news" class="panel"><div style="display:flex;justify-content:space-between"><h2>Kelola Berita</h2><button class="red" onclick="edit()">+ Berita</button></div><div class="box"><table><thead><tr><th>Judul</th><th>Kategori</th><th>Penulis</th><th>Aksi</th></tr></thead><tbody id="rows"></tbody></table></div></section><section id="editorPanel" class="panel"><div class="box"><h2 id="et">Berita</h2><form id="nf"><input type="hidden" name="id"><label>Judul</label><input name="judul" required><div class="grid2"><div><label>Konten</label><div id="q"></div></div><div><label>Kategori</label><select name="kategori"><option>Nasional</option><option>Ekonomi</option><option>Olahraga</option><option>Hiburan</option><option>Kuliner</option></select><label>Meta Description</label><textarea name="meta_desc" maxlength="140" id="md" required></textarea><small id="count">0 / 140</small><label>Meta Tags — maksimal 4</label><input name="meta_tags"><label>Gambar</label><input type="file" id="img" accept="image/*"><input name="gambar" id="url" placeholder="atau URL gambar"></div></div><br><button class="red">Simpan</button> <button type="button" onclick="show('news')">Batal</button></form></div></section><?php if($user['role']==='admin'): ?><section id="menu" class="panel"><div class="grid2"><div class="box"><h2>Menu</h2><table id="mt"></table></div><form class="box" id="mf"><input type="hidden" name="id"><input name="nama" placeholder="Nama menu" required><input name="link" placeholder="index.html" required><button class="red">Simpan</button></form></div></section><section id="users" class="panel"><div class="grid2"><div class="box"><h2>Users</h2><table id="ut"></table></div><form class="box" id="uf"><input type="hidden" name="id"><input name="username" placeholder="Username" required><input name="password" type="password" placeholder="Password"><select name="role"><option>penulis</option><option>admin</option></select><button class="red">Simpan</button></form></div></section><?php endif; ?></main></div><script>let user=<?=json_encode($user)?>,N=[],Q=new Quill('#q',{theme:'snow',modules:{toolbar:[['bold','underline'],[{header:[1,2,3,false]}],[{align:[]}],[{list:'ordered'},{list:'bullet'}],['link','image']]}});const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));async function api(a,f){let r=await fetch('?api='+a,{method:f?'POST':'GET',body:f});let j=await r.json();if(!j.success)throw Error(j.message);return j.data}function show(x){document.querySelectorAll('.panel').forEach(e=>e.classList.remove('on'));document.getElementById(x).classList.add('on');if(x==='news')loadN();if(x==='menu')loadM();if(x==='users')loadU()}async function loadN(){N=await api('admin-news');N.sort((a,b)=>new Date(b.tanggal)-new Date(a.tanggal));total.textContent=N.length;rows.innerHTML=N.map(n=>{let own=user.role==='admin'||n.nama_penulis===user.username;return `<tr><td>${esc(n.judul)}</td><td>${esc(n.kategori)}</td><td>${esc(n.nama_penulis)}</td><td>${own?`<button onclick='edit(${JSON.stringify(n)})'>Edit</button> <button class="danger" onclick="delN('${n.id}')">Hapus</button>`:'Read only'}</td></tr>`}).join('')}function edit(n=null){show('editorPanel');nf.reset();Q.setContents([]);if(n){nf.id.value=n.id;nf.judul.value=n.judul;nf.kategori.value=n.kategori;nf.meta_desc.value=n.meta_desc;nf.meta_tags.value=n.meta_tags;nf.gambar.value=n.gambar;Q.root.innerHTML=n.konten;et.textContent='Edit Berita'}else et.textContent='Berita Baru';count.textContent=nf.meta_desc.value.length+' / 140'}async function delN(id){if(confirm('Hapus berita?')){let f=new FormData;f.append('id',id);await api('delete-news',f);loadN()}}md.oninput=()=>count.textContent=md.value.length+' / 140';nf.onsubmit=async e=>{e.preventDefault();let f=new FormData(nf);let tags=f.get('meta_tags').split(',').filter(x=>x.trim());if(tags.length>4)return alert('Maksimal 4 tag');f.set('konten',Q.root.innerHTML);if(img.files[0]){let u=new FormData;u.append('file',img.files[0]);f.set('gambar',await api('upload',u))}await api('save-news',f);alert('Tersimpan');show('news')};async function loadM(){let a=await api('admin-menu');mt.innerHTML='<tr><th>Nama</th><th>Link</th><th></th></tr>'+a.map(x=>`<tr><td>${esc(x.nama)}</td><td>${esc(x.link)}</td><td><button onclick='mf.id.value="${x.id}";mf.nama.value=${JSON.stringify(x.nama)};mf.link.value=${JSON.stringify(x.link)}'>Edit</button> <button class="danger" onclick="delM('${x.id}')">Hapus</button></td></tr>`).join('')}mf.onsubmit=async e=>{e.preventDefault();await api('save-menu',new FormData(mf));mf.reset();loadM()};async function delM(id){let f=new FormData;f.append('id',id);await api('delete-menu',f);loadM()}async function loadU(){let a=await api('users');ut.innerHTML='<tr><th>Username</th><th>Role</th><th></th></tr>'+a.map(x=>`<tr><td>${esc(x.username)}</td><td>${esc(x.role)}</td><td><button onclick='uf.id.value="${x.id}";uf.username.value=${JSON.stringify(x.username)};uf.role.value=${JSON.stringify(x.role)}'>Edit</button> <button class="danger" onclick="delU('${x.id}')">Hapus</button></td></tr>`).join('')}uf.onsubmit=async e=>{e.preventDefault();await api('save-user',new FormData(uf));uf.reset();loadU()};async function delU(id){let f=new FormData;f.append('id',id);await api('delete-user',f);loadU()}async function logout(){await api('logout',new FormData);location.reload()}loadN();</script><?php endif; ?></body></html><?php exit;} ?>
