else: $hero=$news[0]??null;?><div class="section"><h2>Headline</h2></div><?php if($hero):?><div class="hero"><article><a href="?id=<?=h($hero['id'])?>"><img src="<?=h(pic($hero['gambar']))?>" alt="<?=h($hero['judul'])?>"><div class="pad"><div class="cat"><?=h($hero['kategori'])?></div><h1><?=h($hero['judul'])?></h1><div class="meta"><?=date('d F Y',strtotime($hero['tanggal']))?> · <?=h($hero['nama_penulis'])?></div></div></a></article><div class="side"><?php foreach(array_slice($news,1,3) as $n):?><article><a href="?id=<?=h($n['id'])?>"><img src="<?=h(pic($n['gambar']))?>" alt="<?=h($n['judul'])?>"></a><div class="pad"><div class="cat"><?=h($n['kategori'])?></div><b><?=h($n['judul'])?></b></div></article><?php endforeach;?></div></div><?php else:?><div class="article"><h2>Belum ada berita.</h2><p>Login ke CMS untuk menerbitkan berita pertama.</p></div><?php endif;?><div class="layout"><div><?php foreach(['Nasional','Ekonomi','Olahraga','Hiburan','Kuliner'] as $c):$arr=array_slice(array_filter($news,fn($x)=>($x['kategori']??'')===$c),0,6);?><section><div class="section"><h2><?=h($c)?></h2></div><div class="grid"><?php foreach($arr as $n):?><article class="card"><a href="?id=<?=h($n['id'])?>"><img src="<?=h(pic($n['gambar']))?>" alt="<?=h($n['judul'])?>"><div class="pad"><div class="cat"><?=h($n['kategori'])?></div><h3><?=h($n['judul'])?></h3><div class="meta"><?=date('d M Y',strtotime($n['tanggal']))?></div></div></a></article><?php endforeach;?></div></section><?php endforeach;?></div><aside><div class="section"><h2>Berita Populer</h2></div><div class="popular"><?php foreach(array_slice($news,0,7) as $i=>$n):?><div class="pop"><div class="num">0<?=($i+1)?></div><a href="?id=<?=h($n['id'])?>"><b><?=h($n['judul'])?></b><div class="meta"><?=h($n['kategori'])?></div></a></div><?php endforeach;?></div></aside></div><?php endif;?></main><footer><div class="wrap foot"><img src="uploads/logo_KSA.jpg" alt="INDONEWSTODAY.COM"><span>© <?=date('Y')?> INDONEWSTODAY.COM — INT Media Network.</span></div></footer></body></html>
